import "math"

// Chunk splits s into contiguous sub-slices of at most n elements each.
func Chunk[T any](s []T, n int) [][]T {
	if n < 1 {
		return nil
	}
	out := make([][]T, 0, int(math.Ceil(float64(len(s))/float64(n))))
	for i := 0; i < len(s); i += n {
		end := i + n
		if end > len(s) {
			end = len(s)
		}
		out = append(out, s[i:end])
	}
	return out
}

