import "strings"

// Balanced reports whether the brackets ()[]{} in s are correctly
// balanced and nested, ignoring other characters.
func Balanced(s string) bool {
	stack := []rune{}
	bracketPairs := map[rune]rune{')': '(', ']': '[', '}': '{'}
	openBrackets := "([{"

	for _, r := range s {
		if strings.ContainsRune(openBrackets, r) {
			stack = append(stack, r)
		} else if closer, ok := bracketPairs[r]; ok {
			if len(stack) == 0 || stack[len(stack)-1] != closer {
				return false
			}
			stack = stack[:len(stack)-1]
		}
	}
	return len(stack) == 0
}

