// Merge combines overlapping intervals and returns them sorted by start.
func Merge(in [][2]int) [][2]int {
	if len(in) == 0 {
		return nil
	}

	// Sort intervals by start.
	sort.Slice(in, func(i, j int) bool {
		return in[i][0] < in[j][0]
	})

	out := make([][2]int, 0, len(in))
	start, end := in[0][0], in[0][1]

	for _, itv := range in[1:] {
		if itv[0] <= end { // overlap
			if itv[1] > end {
				end = itv[1]
			}
			continue
		}
		out = append(out, [2]int{start, end})
		start, end = itv[0], itv[1]
	}
	out = append(out, [2]int{start, end})
	return out
}

