// RomanToInt converts a valid uppercase Roman numeral to its integer value.
func RomanToInt(s string) int {
	s = strings.ToUpper(s)
	total := 0
	prev := 0
	for i := len(s) - 1; i >= 0; i-- {
		switch s[i] {
		case 'I':
			total += 1
		case 'V':
			if prev > 1 {
				total -= 5
			} else {
				total += 5
			}
		case 'X':
			if prev > 10 {
				total -= 10
			} else {
				total += 10
			}
		case 'L':
			if prev > 50 {
				total -= 50
			} else {
				total += 50
			}
		case 'C':
			if prev > 100 {
				total -= 100
			} else {
				total += 100
			}
		case 'D':
			if prev > 500 {
				total -= 500
			} else {
				total += 500
			}
		case 'M':
			total += 1000
		}
		prev = value(s[i])
	}
	return total
}

