// Decode expands a run-length encoding string like "a3b2c1" into "aaabbc".
func Decode(s string) string {
	runes := []rune(s)
	var out strings.Builder
	i := 0
	for i < len(runes) {
		if runes[i] < '0' || runes[i] > '9' {
			count := 1
			if i+1 < len(runes) && runes[i+1] >= '0' && runes[i+1] <= '9' {
				count, _ = strconv.Atoi(string(runes[i+1]))
				i++
			}
			out.WriteString(strings.Repeat(string(runes[i]), count))
		}
		i++
	}
	return out.String()
}

