// Caesar shifts each ASCII letter in s by n positions, wrapping within its case.
// Non-letter runes are left unchanged.
func Caesar(s string, n int) string {
	runes := []rune(s)
	for i, r := range runes {
		switch {
		case r >= 'a' && r <= 'z':
			runes[i] = 'a' + (r-'a'+rune(n))%26
		case r >= 'A' && r <= 'Z':
			runes[i] = 'A' + (r-'A'+rune(n))%26
		}
	}
	return string(runes)
}

