// Ring is a fixed-capacity circular buffer of ints.
type Ring struct {
	buf  []int
	head int
	n    int
}

// NewRing returns a new Ring of capacity cap.
func NewRing(cap int) *Ring { return &Ring{buf: make([]int, cap)} }

// Push appends v, evicting the oldest when full.
func (r *Ring) Push(v int) {
	r.buf[(r.head+r.n)%len(r.buf)] = v
	if r.n < len(r.buf) {
		r.n++
	}
	r.head = (r.head + 1) % len(r.buf)
}

// Items returns the elements from oldest to newest.
func (r *Ring) Items() []int {
	out := make([]int, r.n)
	for i := 0; i < r.n; i++ {
		out[i] = r.buf[(r.head+i)%len(r.buf)]
	}
	return out
}

