// LowerBound returns the index of the first element >= target in the sorted slice s.
// If target is greater than any element, it returns len(s).
func LowerBound(s []int, target int) int {
	lo, hi := 0, len(s)
	for lo < hi {
		mid := int(uint(lo+hi) >> 1) // avoids overflow
		if s[mid] < target {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	return lo
}

