// Rotate rotates an NxN matrix 90 degrees clockwise in place.
func Rotate(m [][]int) {
	n := len(m)
	for layer := 0; layer < n/2; layer++ {
		first, last := layer, n - layer - 1
		for i := first; i < last; i++ {
			offset := i - first
			// Save the top element.
			top := m[first][i]
			// Move left -> top.
			m[first][i] = m[last-offset][first]
			// Move bottom -> left.
			m[last-offset][first] = m[last][last-offset]
			// Move right -> bottom.
			m[last][last-offset] = m[i][last]
			// Move top -> right.
			m[i][last] = top
		}
	}
}

func main() {
	m := [][]int{
		{1, 2, 3},
		{4, 5, 6},
		{7, 8, 9},
	}
	Rotate(m)
	for _, row := range m {
		fmt.Println(row)
	}
}

