// ParallelSum sums nums using exactly workers goroutines.
func ParallelSum(nums []int, workers int) int {
	jobs := make(chan int)
	results := make(chan int)
	var wg sync.WaitGroup

	// Start workers that read from jobs and send their sum to results.
	for i := 0; i < workers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			sum := 0
			for n := range jobs {
				sum += n
			}
			results <- sum
		}()
	}

	// Feed jobs with nums and close jobs once done.
	go func() {
		for _, n := range nums {
			jobs <- n
		}
		close(jobs)
	}()

	// Collect results from workers and sum them.
	total := 0
	for i := 0; i < workers; i++ {
		total += <-results
	}
	wg.Wait()
	close(results)
	return total
}

