// IntHeap is a min-heap of ints.
type IntHeap []int

func (h IntHeap) Len() int           { return len(h) }
func (h IntHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h IntHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }

func (h *IntHeap) Push(x any) { *h = append(*h, x.(int)) }

func (h *IntHeap) Pop() any {
	old := *h
	v := old[len(old)-1]
	*h = old[:len(old)-1]
	return v
}

// PopAllSorted returns vals sorted ascending via a min-heap.
func PopAllSorted(vals []int) []int {
	h := IntHeap(vals)
	heap.Init(&h)
	for h.Len() > 0 {
		vals[h.Len()-1] = heap.Pop(&h).(int)
	}
	return vals
}

