	"time"
)

// BucketByHour counts how many timestamps fall into each hour bucket.
func BucketByHour(ts []time.Time) map[time.Time]int {
	buckets := map[time.Time]int{}
	for _, t := range ts {
		hour := t.Truncate(time.Hour)
		buckets[hour]++
	}
	return buckets
}

package sandbox

import (
	"context"
)

// CountUntil consumes ints from ch until ctx is cancelled or ch is closed,
// and returns the count of how many were received.
func CountUntil(ctx context.Context, ch <-chan int) int {
	count := 0
	for {
		select {
		case <-ctx.Done():
			return count
		case _, ok := <-ch:
			if !ok {
				return count
			}
			count++
		}
	}
}

package sandbox

import (
	"io"
	"bytes"
)

// ReadChunks reads r fully and splits the bytes into chunks of at most size.
func ReadChunks(r io.Reader, size int) ([][]byte, error) {
	var chunks [][]byte
	buf := make([]byte, size)
	for {
		n, err := r.Read(buf)
		if n > 0 {
			chunks = append(chunks, buf[:n])
		}
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
	}
	return chunks, nil
}

package sandbox

import (
	"net/http"
)

// Chain applies mws so the first one in the list is the outermost.
func Chain(h http.Handler, mws ...func(http.Handler) http.Handler) http.Handler {
	for i := len(mws) - 1; i >= 0; i-- {
		h = mws[i](h)
	}
	return h
}
